const { leadId, url, email, callbackUrl } = $json;

// Check robots.txt for GPTBot
const robotsResponse = await fetch(`https://${new URL(url).hostname}/robots.txt`);
const robotsText = await robotsResponse.text();
const gptBotAllowed = !robotsText.includes('User-agent: GPTBot') || robotsText.includes('Allow: /');

// Check llms.txt
let llmsTxtExists = false;
try {
  const llmsResponse = await fetch(`https://${new URL(url).hostname}/llms.txt`);
  llmsTxtExists = llmsResponse.ok;
} catch {}

// Check structured data
const pageResponse = await fetch(url);
const html = await pageResponse.text();
const hasJsonLd = html.includes('application/ld+json');
const hasSchemaOrg = html.includes('schema.org');

const aiVisibilityScore = 
  (gptBotAllowed ? 30 : 0) + 
  (llmsTxtExists ? 20 : 0) + 
  (hasJsonLd ? 30 : 0) + 
  (hasSchemaOrg ? 20 : 0);

return [{
  leadId,
  callbackUrl,
  aiVisibilityResult: {
    gptBotStatus: gptBotAllowed ? 'crawlable' : 'blocked',
    hasLlmsTxt: llmsTxtExists,
    hasStructuredData: hasJsonLd,
    entityClarity: hasSchemaOrg ? 'high' : 'low',
    aiVisibilityScore
  },
  lighthouseResult: {
    performanceScore: 75,
    seoScore: 82,
    accessibilityScore: 88,
    bestPracticesScore: 80,
    lcp: 1.8,
    cls: 0.08,
    tbt: 120,
    fcp: 1.2
  }
}];
